mapper.select:
SELECT o.ORDER_ID, o.ORDER_NO, o.ORDER_DATE, o.ORDER_STATUS, o.PAY_AMOUNT, o.CONFIRM_YN, d.COURIER_NAME, d.COURIER_CODE, d.TRACKING_NO, b.BIZ_NAME, pay.TOSS_ORDER_ID AS ORDER_GROUP_ID FROM TB_ORDER o JOIN TB_BUSINESS b ON b.BIZ_NO = o.BIZ_NO LEFT JOIN TB_ORDER_DELIVERY d ON d.ORDER_ID = o.ORDER_ID LEFT JOIN TB_PAYMENT pay ON pay.ORDER_ID = o.ORDER_ID WHERE o.MEMBER_NO = #{memberNo}
AND o.ORDER_STATUS = #{statusCd}
ORDER BY o.ORDER_ID DESC

mapper.update:
UPDATE TB_ORDER
   SET CONFIRM_YN = 'Y', CONFIRMED_AT = SYSDATE
 WHERE ORDER_ID = #{orderId}
   AND MEMBER_NO = #{memberNo}
   AND ORDER_STATUS = 'DONE'
   AND CONFIRM_YN = 'N'
